class Solution {
  public int minOperations(int[] nums1, int[] nums2) {
    int noSwap = operations(nums1, nums2, false);
    int swap = operations(nums1, nums2, true);
    if (noSwap < 0 && swap < 0) return -1;
    if (noSwap < 0) return swap;
    if (swap < 0) return noSwap;
    return Math.min(noSwap, swap);
  }

  private int operations(int[] a, int[] b, boolean swapLast) {
    int n = a.length, lastA = a[n - 1], lastB = b[n - 1], count = swapLast ? 1 : 0;
    if (swapLast) {
      int temp = lastA;
      lastA = lastB;
      lastB = temp;
    }
    for (int i = 0; i < n - 1; i++) {
      if (a[i] <= lastA && b[i] <= lastB) continue;
      if (b[i] <= lastA && a[i] <= lastB) count++;
      else return -1;
    }
    return count;
  }
}
